#include "core/config_loader.h"
#include "core/event_bus.h"
#include "qq_common.h"
#include <stdio.h>
#include <cjson/cJSON.h> // Assumed dependency

// Helper to read a whole file into a string
static char* read_file_to_string(const char* path) { /* ... implementation ... */ return buffer; }

bool config_load_and_dispatch(const char* path, qq_engine_config_t* out_config, event_bus_t* bus) {
    char* json_string = read_file_to_string(path);
    if (!json_string) {
        // Log error: could not open/read config file
        return false;
    }

    cJSON* root = cJSON_Parse(json_string);
    free(json_string);
    if (!root) {
        // Log error: cJSON parse error
        return false;
    }

    cJSON* engine_obj = cJSON_GetObjectItem(root, "engine");
    cJSON* audio_obj = cJSON_GetObjectItem(engine_obj, "audio");
    cJSON* master_volume_item = cJSON_GetObjectItem(audio_obj, "master_volume");

    if (cJSON_IsNumber(master_volume_item)) {
        out_config->master_volume = (float)master_volume_item->valuedouble;
    } else {
        // Log warning: master_volume not found or invalid, using default
        out_config->master_volume = 1.0f;
    }

    cJSON_Delete(root);

    // Dispatch the event to notify other systems
    qq_event_t volume_event;
    volume_event.type = QQ_EVENT_MASTER_VOLUME_CHANGED;
    volume_event.data.master_volume_changed.new_volume = out_config->master_volume;
    event_bus_dispatch(bus, &volume_event);

    return true;
}
